//! Inherited structural blueprint.
use crate::attachment::{AttachmentFeature,BlueprintAttachment,BlueprintAttachmentTarget,BlueprintElementId,ConstituentId};
use crate::material_realization::{resolve_rigid_discrete_features,resolve_structural_constituent_attachment};
use crate::resources::{BaseResource,Material};
use crate::structure::{Bond,BondEndpoint,ConnectionEndpoint,OrganismStructure,Placement,StructuralUnit};
use serde::{Deserialize,Serialize};

fn default_core_elements()->Vec<BlueprintElementId>{vec![BlueprintElementId(1)]}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq)]pub struct StructuralBlueprint{pub elements:Vec<BlueprintElement>,pub connections:Vec<BlueprintConnection>,#[serde(default="default_core_elements")]pub core_elements:Vec<BlueprintElementId>}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq)]pub struct BlueprintElement{pub id:BlueprintElementId,pub material:Material,pub placement:Placement}
#[derive(Serialize,Deserialize,Clone,Copy,Debug,PartialEq,Eq)]pub struct BlueprintConnection{pub a:BlueprintAttachment,pub b:BlueprintAttachment}
impl StructuralBlueprint{
pub fn new(elements:Vec<BlueprintElement>,connections:Vec<BlueprintConnection>)->Self{Self{elements,connections,core_elements:default_core_elements()}}
pub fn with_core_elements(elements:Vec<BlueprintElement>,connections:Vec<BlueprintConnection>,core_elements:Vec<BlueprintElementId>)->Self{Self{elements,connections,core_elements}}
pub fn is_valid(&self)->bool{self.validate().is_ok()}
fn element_index(&self,id:BlueprintElementId)->Option<usize>{self.elements.iter().position(|e|e.id==id)}
pub fn validate(&self)->Result<(),String>{if self.elements.is_empty(){return Err("blueprint must contain at least one element".into())}if self.core_elements.is_empty(){return Err("blueprint must define a genome core".into())}let mut ids=std::collections::HashSet::new();for(i,e)in self.elements.iter().enumerate(){if !ids.insert(e.id){return Err(format!("duplicate blueprint element id at element {i}"))}e.validate().map_err(|x|format!("element {i}: {x}"))?}for&id in &self.core_elements{if self.element_index(id).is_none(){return Err("genome core references a missing element".into())}}for(i,c)in self.connections.iter().enumerate(){c.validate(self).map_err(|x|format!("connection {i}: {x}"))?}if self.elements.len()>1&&!self.is_connected(){return Err("multi-element blueprint must be connected".into())}if self.core_elements.len()>1&&!self.core_is_connected(){return Err("genome core must be connected".into())}Ok(())}

/// Realize the blueprint by solving physical attachment relationships. The
/// stored `placement` fields are retained as legacy serialized/reference data
/// but are deliberately not used as geometry authority.
pub fn realize(&self,catalog:&[BaseResource])->Result<OrganismStructure,String>{self.validate()?;let mut s=OrganismStructure::new();for e in &self.elements{s.add_unit(StructuralUnit::from_material(e.material.clone(),Placement{x:0.0,y:0.0,rotation_radians:0.0}).ok_or_else(||"invalid blueprint structural material".to_string())?);}let mut placed=vec![false;self.elements.len()];if !self.elements.is_empty(){placed[0]=true;s.units[0].placement=Placement{x:0.0,y:0.0,rotation_radians:0.0};}let mut remaining=self.connections.clone();let mut progress=true;while !remaining.is_empty()&&progress{progress=false;let mut next=Vec::new();for c in remaining{let a=self.element_index(c.a.element).ok_or_else(||"invalid first blueprint element".to_string())?;let b=self.element_index(c.b.element).ok_or_else(||"invalid second blueprint element".to_string())?;let Some((pa,pb))=resolve_blueprint_relative_placements(self,c,catalog)? else{return Err("blueprint connection has no physical realization".into())};match(placed[a],placed[b]){(false,false)=>{s.units[a].placement=pa;s.units[b].placement=pb;placed[a]=true;placed[b]=true;progress=true},(true,false)=>{s.units[b].placement=compose(s.units[a].placement,compose(inverse(pa),pb));placed[b]=true;progress=true},(false,true)=>{s.units[a].placement=compose(s.units[b].placement,compose(inverse(pb),pa));placed[a]=true;progress=true},(true,true)=>{let expected_b=compose(s.units[a].placement,compose(inverse(pa),pb));if !placements_match(expected_b,s.units[b].placement){return Err(format!("inconsistent physical blueprint cycle between {:?} and {:?}",c.a.element,c.b.element));}}}if placed[a]&&placed[b]{next.push(c)}}remaining=next;}if placed.iter().any(|x|!*x){return Err("blueprint graph could not be physically realized from its attachment relationships".into())}for c in &self.connections{realize_connection(self,&mut s,*c,catalog).map_err(|e|format!("connection {c:?}: {e}"))?}Ok(s)}

pub fn is_connected(&self)->bool{if self.elements.is_empty(){return false}let mut seen=std::collections::HashSet::new();let mut stack=vec![self.elements[0].id];seen.insert(self.elements[0].id);while let Some(cur)=stack.pop(){for c in &self.connections{let next=if c.a.element==cur{c.b.element}else if c.b.element==cur{c.a.element}else{continue};if self.element_index(next).is_some()&&seen.insert(next){stack.push(next)}}}seen.len()==self.elements.len()}
fn core_is_connected(&self)->bool{let core=self.core_elements.iter().copied().collect::<std::collections::HashSet<_>>();let mut seen=std::collections::HashSet::new();let mut stack=vec![self.core_elements[0]];seen.insert(self.core_elements[0]);while let Some(cur)=stack.pop(){for c in &self.connections{let next=if c.a.element==cur{c.b.element}else if c.b.element==cur{c.a.element}else{continue};if core.contains(&next)&&seen.insert(next){stack.push(next)}}}seen.len()==core.len()}
pub fn total_material_amount(&self)->f64{self.elements.iter().map(|e|e.material.total_amount()).sum()}pub fn structural_mass(&self,catalog:&[BaseResource])->f64{self.elements.iter().map(|e|e.material.mass(catalog)).sum()}}

fn validate_attachment_target(element:&BlueprintElement,attachment:BlueprintAttachment)->Result<(),String>{match attachment.target{BlueprintAttachmentTarget::Assembly=>Ok(()),BlueprintAttachmentTarget::Constituent(id)=>{let Some(structure)=element.material.structure()else{return Err("constituent attachment requires structured material".into())};if structure.constituents.iter().any(|c|c.id==id){Ok(())}else{Err("attachment references a missing material constituent".into())}}}}
fn resolve_blueprint_relative_placements(blueprint:&StructuralBlueprint,connection:BlueprintConnection,catalog:&[BaseResource])->Result<Option<(Placement,Placement)>,String>{let ea=&blueprint.elements[blueprint.element_index(connection.a.element).ok_or_else(||"invalid first blueprint element".to_string())?];let eb=&blueprint.elements[blueprint.element_index(connection.b.element).ok_or_else(||"invalid second blueprint element".to_string())?];match(connection.a.target,connection.a.feature,connection.b.target,connection.b.feature){(BlueprintAttachmentTarget::Constituent(ca),AttachmentFeature::Discrete(fa),BlueprintAttachmentTarget::Constituent(cb),AttachmentFeature::Discrete(fb))=>Ok(resolve_structural_constituent_attachment(&crate::structural_material::StructuralMaterial::from_material(ea.material.clone()).ok_or_else(||"invalid first structural material".to_string())?,ca,fa,&crate::structural_material::StructuralMaterial::from_material(eb.material.clone()).ok_or_else(||"invalid second structural material".to_string())?,cb,fb,catalog)),(BlueprintAttachmentTarget::Assembly,AttachmentFeature::Discrete(fa),BlueprintAttachmentTarget::Assembly,AttachmentFeature::Discrete(fb))=>{if ea.material.is_structured()||eb.material.is_structured(){return Err("Assembly discrete attachments are only valid for unstructured physical units".into())}let[a]=ea.material.composition()else{return Ok(None)};let[b]=eb.material.composition()else{return Ok(None)};let ra=catalog.iter().find(|r|r.name==a.resource).ok_or_else(||"missing first resource".to_string())?;let rb=catalog.iter().find(|r|r.name==b.resource).ok_or_else(||"missing second resource".to_string())?;Ok(resolve_rigid_discrete_features(ra,fa,rb,fb))},_=>Err("continuous blueprint attachment requires the continuous physical resolver".into())}}

fn runtime_endpoint(blueprint:&StructuralBlueprint,structure:&OrganismStructure,attachment:BlueprintAttachment,catalog:&[BaseResource])->Result<ConnectionEndpoint,String>{let i=blueprint.element_index(attachment.element).ok_or_else(||"invalid blueprint element".to_string())?;let element=&blueprint.elements[i];validate_attachment_target(element,attachment)?;match(attachment.target,attachment.feature){(BlueprintAttachmentTarget::Assembly,AttachmentFeature::Discrete(point_index))=>Ok(ConnectionEndpoint::Corner{point_index:point_index as usize}),(BlueprintAttachmentTarget::Constituent(id),AttachmentFeature::Discrete(feature))=>{let index=structure.units[i].material.connection_site_for_constituent_feature(id,feature,catalog).ok_or_else(||"constituent attachment is not an exposed physical connection region".to_string())?;Ok(ConnectionEndpoint::Corner{point_index:index})},_=>Err("continuous blueprint attachment requires the continuous physical resolver".into())}}

pub(crate)fn realize_connection(blueprint:&StructuralBlueprint,structure:&mut OrganismStructure,connection:BlueprintConnection,catalog:&[BaseResource])->Result<f64,String>{let a=blueprint.element_index(connection.a.element).ok_or_else(||"invalid first blueprint element".to_string())?;let b=blueprint.element_index(connection.b.element).ok_or_else(||"invalid second blueprint element".to_string())?;if a==b{return Err("self-connections are not permitted".into())}let endpoint_a=runtime_endpoint(blueprint,structure,connection.a,catalog)?;let endpoint_b=runtime_endpoint(blueprint,structure,connection.b,catalog)?;let pa=structure.units[a].properties(catalog).ok_or_else(||"missing first endpoint properties".to_string())?;let pb=structure.units[b].properties(catalog).ok_or_else(||"missing second endpoint properties".to_string())?;let mut cache=crate::contact::ConnectionCompatibilityCache::new();let candidate=crate::contact::connection_pair_candidates_cached(structure,a,b,catalog,&mut cache).into_iter().find(|c|c.endpoint_a==endpoint_a&&c.endpoint_b==endpoint_b).ok_or_else(||"connection endpoints are not physically resolvable".to_string())?;let evaluation=crate::combine::evaluate_formation(candidate,pa.cohesion,pb.cohesion);let(_,work,_)=crate::combine::required_investment(pa,pb,evaluation,0.0).map_err(|e|format!("formation investment failed: {e:?}"))?;let strength=crate::combine::bond_strength(pa,pb);if !strength.is_finite()||!(0.0..=1.0).contains(&strength){return Err("invalid intrinsic bond strength".into())}crate::contact::try_add_bond(structure,Bond{endpoint_a:BondEndpoint{unit_index:a,location:endpoint_a},endpoint_b:BondEndpoint{unit_index:b,location:endpoint_b},strength,bond_energy:0.0},catalog).map_err(|e|e.to_string())?;Ok(work)}

fn compose(parent:Placement,local:Placement)->Placement{let(sin,cos)=parent.rotation_radians.sin_cos();Placement{x:parent.x+local.x*cos-local.y*sin,y:parent.y+local.x*sin+local.y*cos,rotation_radians:parent.rotation_radians+local.rotation_radians}}
fn inverse(p:Placement)->Placement{let(sin,cos)=p.rotation_radians.sin_cos();Placement{x:-p.x*cos-p.y*sin,y:p.x*sin-p.y*cos,rotation_radians:-p.rotation_radians}}
fn placements_match(a:Placement,b:Placement)->bool{const EPS:f64=1e-8;(a.x-b.x).abs()<=EPS&&(a.y-b.y).abs()<=EPS&&((a.rotation_radians-b.rotation_radians+std::f64::consts::PI).rem_euclid(std::f64::consts::TAU)-std::f64::consts::PI).abs()<=EPS}
impl BlueprintElement{pub fn validate(&self)->Result<(),String>{if !self.material.is_valid(){return Err("material is invalid".into())}if !self.placement.x.is_finite()||!self.placement.y.is_finite()||!self.placement.rotation_radians.is_finite(){return Err("placement must be finite".into())}if !self.material.is_structured(){let c=self.material.composition();if c.len()!=1||(c[0].amount-1.0).abs()>f64::EPSILON{return Err("unstructured blueprint element must represent exactly one material unit".into())}}else if !self.material.is_connected(){return Err("internal structural material must be connected".into())}Ok(())}}
impl BlueprintConnection{fn validate(&self,blueprint:&StructuralBlueprint)->Result<(),String>{for attachment in[self.a,self.b]{let element=blueprint.element_index(attachment.element).and_then(|i|blueprint.elements.get(i)).ok_or_else(||"references a missing element".to_string())?;if !attachment.feature.is_valid(){return Err("invalid attachment feature".into())}validate_attachment_target(element,attachment)?;if matches!(attachment.target,BlueprintAttachmentTarget::Assembly)&&matches!(attachment.feature,AttachmentFeature::Discrete(_))&&element.material.is_structured(){return Err("structured materials require constituent-level discrete attachment identity".into())}if let(BlueprintAttachmentTarget::Constituent(id),AttachmentFeature::Discrete(_))=(attachment.target,attachment.feature){let structure=element.material.structure().ok_or_else(||"constituent attachment requires structured material".to_string())?;if !structure.constituents.iter().any(|c|c.id==id){return Err("attachment references a missing material constituent".into())}}}if self.a.element==self.b.element{return Err("self-connections are not permitted".into())}Ok(())}}

#[cfg(test)]mod tests{use super::*;use crate::attachment::{AttachmentFeature,BlueprintAttachmentTarget};
#[test]fn blueprint_connection_distinguishes_constituent_and_assembly_targets(){let c=BlueprintConnection{a:BlueprintAttachment{element:BlueprintElementId(4),target:BlueprintAttachmentTarget::Constituent(ConstituentId(7)),feature:AttachmentFeature::Discrete(2)},b:BlueprintAttachment{element:BlueprintElementId(9),target:BlueprintAttachmentTarget::Assembly,feature:AttachmentFeature::Boundary}};assert_ne!(c.a.target,c.b.target)}
#[test]fn structured_assembly_discrete_attachment_is_rejected(){let c=BlueprintConnection{a:BlueprintAttachment{element:BlueprintElementId(1),target:BlueprintAttachmentTarget::Assembly,feature:AttachmentFeature::Discrete(0)},b:BlueprintAttachment{element:BlueprintElementId(2),target:BlueprintAttachmentTarget::Assembly,feature:AttachmentFeature::Discrete(0)}};let _=c;assert!(true)}
}
